package basics;

public class MultiplicationTable {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int value = 12;
		  System.out.println("Multiplication Table of 12");
		int i = 1;
		while(i<=10) {
			System.out.println(i + "*" + value  + "=" + (i * 12));
			i++;
		}
		

	}

}
